"""Offline memory lifecycle and task routing; no semantic extraction or database."""
from dataclasses import dataclass, replace
import json

@dataclass(frozen=True)
class Scope:
    tenant: str
    user: str

@dataclass(frozen=True)
class Memory:
    memory_id: str
    scope: Scope
    key: str
    value: str
    source: str
    version: int
    expires_at: int
    status: str = 'active'
    supersedes: str | None = None

class Store:
    def __init__(self):
        self.rows = {}
        self.heads = {}
        self.outputs = {}
        self.invalid_outputs = set()
        self.counter = 0

    def _invalidate(self, memory_id, status):
        row = self.rows[memory_id]
        self.rows[memory_id] = replace(row, status=status)
        for output_id, dependencies in self.outputs.items():
            if memory_id in dependencies:
                self.invalid_outputs.add(output_id)

    def put(self, scope, key, value, source, expires_at, now,
            confirmed, expected_version=0):
        if not confirmed or not source or expires_at <= now or key == 'approval':
            raise ValueError('INELIGIBLE')
        slot = (scope, key)
        old_id = self.heads.get(slot)
        old = self.rows.get(old_id)
        version = old.version if old else 0
        if version != expected_version:
            raise ValueError('CONFLICT')
        if old and old.status == 'active' and old.value == value and old.source == source and old.expires_at == expires_at:
            return old.memory_id
        if old:
            self._invalidate(old.memory_id, 'superseded')
        self.counter += 1
        memory_id = f'm{self.counter}'
        self.rows[memory_id] = Memory(memory_id, scope, key, value, source,
                                     version+1, expires_at, supersedes=old_id)
        self.heads[slot] = memory_id
        return memory_id

    def read(self, scope, key, now):
        memory_id = self.heads.get((scope,key))
        if memory_id is None:
            return None
        row = self.rows[memory_id]
        if row.status != 'active':
            return None
        if row.expires_at <= now:
            self._invalidate(memory_id, 'expired')
            return None
        return row

    def delete(self, scope, memory_id):
        row = self.rows[memory_id]
        if row.scope != scope:
            raise PermissionError('SCOPE')
        self._invalidate(memory_id, 'deleted')

    def invalidate_source(self, source):
        for memory_id, row in list(self.rows.items()):
            if row.source == source and row.status == 'active':
                self._invalidate(memory_id, 'source_invalid')

    def record_output(self, output_id, scope, memory_ids, now):
        if output_id in self.outputs:
            raise ValueError('OUTPUT_IMMUTABLE')
        for mid in memory_ids:
            row = self.rows[mid]
            current = self.read(scope, row.key, now)
            if current is None or current.memory_id != mid:
                raise ValueError('STALE_OR_HIDDEN')
        self.outputs[output_id] = frozenset(memory_ids)

@dataclass(frozen=True)
class Task:
    task_id: str
    scope: Scope
    revision: int
    status: str

class Router:
    def __init__(self, tasks):
        self.tasks = {t.task_id:t for t in tasks}
        self.active = None
        self.epoch = 0

    def choose(self, scope, candidate_ids, confirmed_id=None):
        visible = [tid for tid in dict.fromkeys(candidate_ids)
                   if tid in self.tasks and self.tasks[tid].scope == scope
                   and self.tasks[tid].status == 'paused']
        if confirmed_id is None or confirmed_id not in visible:
            return {'status':'CLARIFY', 'candidates':visible}
        self.active = confirmed_id
        self.epoch += 1
        task = self.tasks[confirmed_id]
        return {'status':'ACTIVE', 'task_id':task.task_id,
                'revision':task.revision, 'epoch':self.epoch,
                'approval':'RECHECK_REQUIRED'}

    def accept_result(self, task_id, revision, epoch):
        task = self.tasks.get(task_id)
        return bool(task and self.active == task_id and task.revision == revision
                    and self.epoch == epoch)


def main():
    scope = Scope('t1','u1'); other = Scope('t2','u1')
    s = Store()
    m1 = s.put(scope,'language','zh','preference-event-1',100,0,True)
    assert s.read(other,'language',1) is None
    s.record_output('o1',scope,[m1],1)
    m2 = s.put(scope,'language','en','preference-event-2',100,2,True,1)
    assert s.read(scope,'language',3).value == 'en'
    assert s.rows[m1].status == 'superseded' and 'o1' in s.invalid_outputs
    try:
        s.put(scope,'language','fr','event-3',100,3,True,1)
    except ValueError as e:
        assert str(e) == 'CONFLICT'
    else:
        raise AssertionError('stale write')
    try:
        s.delete(other,m2)
    except PermissionError:
        pass
    else:
        raise AssertionError('cross tenant deletion')
    s.record_output('o2',scope,[m2],3)
    s.invalidate_source('preference-event-2')
    assert s.read(scope,'language',4) is None and 'o2' in s.invalid_outputs
    m3 = s.put(scope,'timezone','Asia/Shanghai','event-4',5,4,True)
    assert s.read(scope,'timezone',5) is None and s.rows[m3].status == 'expired'
    m4 = s.put(scope,'format','concise','event-5',100,4,True)
    s.delete(scope,m4)
    assert s.read(scope,'format',5) is None
    try:
        s.put(scope,'approval','all writes','event-6',100,5,True)
    except ValueError:
        pass
    else:
        raise AssertionError('approval retained')
    router = Router([Task('research',scope,1,'paused'),Task('issue',scope,2,'paused')])
    assert router.choose(scope,['research','issue'])['status'] == 'CLARIFY'
    first = router.choose(scope,['research'],'research')
    second = router.choose(scope,['issue'],'issue')
    assert not router.accept_result('research',1,first['epoch'])
    assert router.accept_result('issue',2,second['epoch'])
    print(json.dumps({'status':'SELF_CHECK_OK', 'invalid_outputs':sorted(s.invalid_outputs),
                      'memory_statuses':{k:v.status for k,v in s.rows.items()},
                      'routing':second}, ensure_ascii=False,sort_keys=True))

if __name__ == '__main__':
    main()

"""Deterministic DAG planning fixture. No LLM, tools, or external side effects."""
from dataclasses import dataclass, replace
import hashlib
import json

@dataclass(frozen=True)
class Node:
    name: str
    deps: tuple[str, ...]
    needs: frozenset[str]
    produces: frozenset[str]
    tool: str
    cost: int
    effect: str = 'read'


def build_plan(goals, initial, recipes):
    """One recipe per artifact in this fixture; ambiguous providers must be resolved upstream."""
    nodes = {}
    visiting = set()
    def ensure(artifact):
        if artifact in initial:
            return None
        if artifact not in recipes:
            raise ValueError('NO_RECIPE:'+artifact)
        node = recipes[artifact]
        if node.name in visiting:
            raise ValueError('RECIPE_CYCLE')
        if node.name in nodes:
            return node.name
        visiting.add(node.name)
        deps = set()
        for required in sorted(node.needs):
            name = ensure(required)
            if name:
                deps.add(name)
        visiting.remove(node.name)
        nodes[node.name] = replace(node, deps=tuple(sorted(deps)))
        return node.name
    for artifact in sorted(goals):
        ensure(artifact)
    return tuple(nodes.values())


def validate(nodes, initial, goals, allowed, budget):
    by_id = {n.name:n for n in nodes}
    if len(by_id) != len(nodes):
        raise ValueError('DUPLICATE_NODE')
    for n in nodes:
        if not set(n.deps) <= by_id.keys():
            raise ValueError('MISSING_DEP')
        if n.tool not in allowed or n.effect != 'read':
            raise ValueError('UNAUTHORIZED')
        if type(n.cost) is not int or n.cost < 0:
            raise ValueError('COST')
    if sum(n.cost for n in nodes) > budget:
        raise ValueError('BUDGET')
    done = set(); ancestors = {}; order = []
    while len(done) < len(nodes):
        ready = sorted(n.name for n in nodes if n.name not in done and set(n.deps) <= done)
        if not ready:
            raise ValueError('CYCLE')
        for name in ready:
            n = by_id[name]
            inherited = set(n.deps)
            for dep in n.deps:
                inherited.update(ancestors[dep])
            available = set(initial)
            for dep in inherited:
                available.update(by_id[dep].produces)
            if not n.needs <= available:
                raise ValueError('INPUT_NOT_REACHABLE:'+name)
            ancestors[name] = inherited
            done.add(name); order.append(name)
    all_outputs = set(initial)
    for n in nodes:
        all_outputs.update(n.produces)
    if not goals <= all_outputs:
        raise ValueError('GOAL_UNSATISFIED')
    return order


def invalidate(nodes, statuses, changed):
    invalid = set(changed)
    while True:
        more = {n.name for n in nodes if set(n.deps) & invalid}
        if more <= invalid:
            break
        invalid.update(more)
    updated = dict(statuses)
    by_id = {n.name:n for n in nodes}
    for name in invalid:
        if name not in by_id:
            raise ValueError('UNKNOWN_NODE')
        updated[name] = ('EFFECT_RECHECK' if statuses.get(name) == 'done'
                         and by_id[name].effect != 'read' else 'stale')
    return updated


class ProgressGuard:
    def __init__(self):
        self.seen = set()
    def observe(self, unresolved, evidence_versions, pending_effects):
        payload = [sorted(unresolved),sorted(evidence_versions),sorted(pending_effects)]
        signature = hashlib.sha256(json.dumps(payload).encode()).hexdigest()
        if signature in self.seen:
            return 'STOP_NO_PROGRESS'
        self.seen.add(signature)
        return 'CONTINUE'


def expect_error(fn, code):
    try:
        fn()
    except ValueError as e:
        assert str(e).startswith(code), (str(e),code)
    else:
        raise AssertionError('expected '+code)


def main():
    report = Node('report',(),frozenset({'report_id'}),frozenset({'failure'}),'read_report',1)
    rule = Node('rule',(),frozenset({'failure'}),frozenset({'policy'}),'read_policy',1)
    draft = Node('draft',(),frozenset({'failure','policy'}),frozenset({'analysis'}),'compose',1)
    recipes = {'failure':report,'policy':rule,'analysis':draft}
    initial = {'report_id'}; goals = {'analysis'}
    nodes = build_plan(goals, initial, recipes)
    allowed = {'read_report','read_policy','compose'}
    order = validate(nodes,initial,goals,allowed,3)
    assert order == ['report','rule','draft']
    by_id = {n.name:n for n in nodes}
    expect_error(lambda:validate([replace(n,deps=('absent',)) if n.name=='draft' else n for n in nodes],initial,goals,allowed,3),'MISSING_DEP')
    expect_error(lambda:validate([replace(n,deps=('draft',)) if n.name=='report' else n for n in nodes],initial,goals,allowed,3),'CYCLE')
    expect_error(lambda:validate([replace(n,deps=()) if n.name=='draft' else n for n in nodes],initial,goals,allowed,3),'INPUT_NOT_REACHABLE')
    expect_error(lambda:validate(nodes,initial,goals,allowed,2),'BUDGET')
    expect_error(lambda:validate(nodes,initial,goals,{'compose'},3),'UNAUTHORIZED')
    expect_error(lambda:build_plan({'unknown'},initial,recipes),'NO_RECIPE')
    statuses = invalidate(nodes,dict.fromkeys(order,'done'),{'rule'})
    assert statuses == {'report':'done','rule':'stale','draft':'stale'}
    effect_nodes = nodes + (Node('issue',('draft',),frozenset({'analysis'}),frozenset({'receipt'}),'write',1,'write'),)
    effect_status = invalidate(effect_nodes,dict.fromkeys(order+['issue'],'done'),{'rule'})
    assert effect_status['issue'] == 'EFFECT_RECHECK'
    guard = ProgressGuard()
    assert guard.observe({'policy'}, {'report@1'},set()) == 'CONTINUE'
    assert guard.observe({'policy'}, {'report@1'},set()) == 'STOP_NO_PROGRESS'
    assert guard.observe(set(), {'report@1','policy@2'},set()) == 'CONTINUE'
    print(json.dumps({'status':'SELF_CHECK_OK','order':order,'after_change':statuses,
                      'external_effect_after_change':effect_status['issue']},sort_keys=True))

if __name__ == '__main__':
    main()

"""Synthetic page blocks and manual vectors; no PDF/OCR/embedding/ANN service."""
from dataclasses import dataclass, replace
import hashlib
import json
import math


def digest(value):
    return hashlib.sha256(json.dumps(value,ensure_ascii=False,sort_keys=True).encode()).hexdigest()


def checked(v):
    if not isinstance(v,(list,tuple)) or not 0 < len(v) <= 1024:
        raise ValueError('VECTOR_DIMENSION')
    values=[]
    for x in v:
        if type(x) not in (int,float):
            raise ValueError('VECTOR_NUMBER')
        try:
            x=float(x)
        except (ValueError,OverflowError):
            raise ValueError('VECTOR_NUMBER') from None
        if not math.isfinite(x) or abs(x)>1e100:
            raise ValueError('VECTOR_FINITE_BOUND')
        values.append(x)
    return tuple(values)


def metrics(a,b):
    a=checked(a); b=checked(b)
    if len(a)!=len(b):
        raise ValueError('VECTOR_DIMENSION')
    na=math.hypot(*a); nb=math.hypot(*b)
    if na==0 or nb==0:
        raise ValueError('ZERO_VECTOR')
    dot=math.fsum(x*y for x,y in zip(a,b))
    return {'dot':dot,'cosine':math.fsum((x/na)*(y/nb) for x,y in zip(a,b)),
            'l2':math.hypot(*(x-y for x,y in zip(a,b)))}

@dataclass(frozen=True)
class Block:
    block_id: str
    page: int
    bbox: tuple
    text: str
    method: str
    verified: bool
    vector: tuple

@dataclass(frozen=True)
class Source:
    doc_id: str
    revision: str
    parser_version: str
    blocks: tuple[Block,...]

@dataclass(frozen=True)
class Chunk:
    chunk_id: str
    doc_id: str
    revision: str
    source_hash: str
    block_id: str
    page: int
    bbox: tuple
    text: str
    text_hash: str
    vector: tuple
    embedding_version: str

@dataclass(frozen=True)
class Snapshot:
    snapshot_id: str
    manifest: tuple
    chunks: tuple[Chunk,...]


def source_hash(source):
    return digest([source.doc_id,source.revision,source.parser_version,
        [[b.block_id,b.page,b.bbox,b.text,b.method,b.verified] for b in source.blocks]])


def content(snapshot):
    return [snapshot.manifest,[[c.chunk_id,c.doc_id,c.revision,c.source_hash,c.block_id,
             c.page,c.bbox,c.text,c.text_hash,c.vector,c.embedding_version] for c in snapshot.chunks]]


def build(sources, embedding_version):
    if len({s.doc_id for s in sources}) != len(sources):
        raise ValueError('DUPLICATE_DOCUMENT')
    chunks=[]; manifest=[]
    for src in sorted(sources,key=lambda x:x.doc_id):
        sh=source_hash(src)
        manifest.append((src.doc_id,src.revision,sh))
        if len({b.block_id for b in src.blocks}) != len(src.blocks):
            raise ValueError('DUPLICATE_BLOCK')
        for b in src.blocks:
            if not b.verified:
                continue
            vector=checked(b.vector)
            if math.hypot(*vector)==0:
                raise ValueError('ZERO_VECTOR')
            th=digest(b.text)
            cid=digest([src.doc_id,src.revision,b.block_id,th,src.parser_version])
            chunks.append(Chunk(cid,src.doc_id,src.revision,sh,b.block_id,b.page,b.bbox,
                                b.text,th,vector,embedding_version))
    snap=Snapshot('',tuple(manifest),tuple(chunks))
    return replace(snap,snapshot_id=digest(content(snap)))


def delta(old,new):
    a={c.chunk_id for c in old.chunks}; b={c.chunk_id for c in new.chunks}
    return {'keep':len(a&b),'add':len(b-a),'delete':len(a-b)}


def query(snapshot,expected_snapshot_id,vector,embedding_version,principal,acl,top_k=3):
    if snapshot.snapshot_id != expected_snapshot_id or digest(content(snapshot)) != snapshot.snapshot_id:
        raise ValueError('SNAPSHOT_MISMATCH')
    if type(top_k) is not int or top_k<1:
        raise ValueError('TOP_K')
    q=checked(vector)
    if math.hypot(*q)==0:
        raise ValueError('ZERO_VECTOR')
    rows=[]
    for c in snapshot.chunks:
        if principal not in acl.get(c.doc_id,frozenset()):
            continue
        if c.embedding_version != embedding_version:
            raise ValueError('MODEL_MISMATCH')
        rows.append((metrics(q,c.vector)['cosine'],c))
    rows.sort(key=lambda pair:(-pair[0],pair[1].chunk_id))
    # acl is a trusted current snapshot. Production reads must re-check at use-time.
    return [c for _,c in rows[:top_k]]


def expect(fn,code):
    try:
        fn()
    except ValueError as e:
        assert str(e)==code,(str(e),code)
    else:
        raise AssertionError(code)


def main():
    assert metrics([1,0],[2,0]) == {'dot':2.0,'cosine':1.0,'l2':1.0}
    a=(0.6,0.8); b=(1.0,0.0)
    m=metrics(a,b)
    assert math.isclose(m['l2']**2,2-2*m['dot'])
    expect(lambda:metrics([0,0],[1,0]),'ZERO_VECTOR')
    expect(lambda:metrics([1],[1,0]),'VECTOR_DIMENSION')
    expect(lambda:metrics([float('nan')],[1]),'VECTOR_FINITE_BOUND')
    block=Block('p1b1',1,(0,0,100,40),'refund rule is less than 7','native',True,(1,0))
    uncertain=Block('p2b1',2,(0,0,100,40),'refund rule is less than 1','ocr',False,(1,0))
    s1=Source('policy','r1','fixture-parser-1',(block,uncertain))
    s2=Source('guide','r1','fixture-parser-1',(replace(block,text='report reading',vector=(0,1)),))
    first=build([s1,s2],'manual-v1')
    assert len(first.chunks)==2
    acl={'policy':frozenset({'u1'}),'guide':frozenset({'u1'})}
    assert query(first,first.snapshot_id,(1,0),'manual-v1','u1',acl)[0].doc_id=='policy'
    changed=replace(s1,revision='r2',blocks=(replace(block,text='refund rule is at most 7'),))
    second=build([changed],'manual-v1')  # guide deleted
    assert delta(first,second)=={'keep':0,'add':1,'delete':2}
    hits=query(second,second.snapshot_id,(1,0),'manual-v1','u1',acl)
    assert all(c.revision=='r2' and c.doc_id=='policy' for c in hits)
    acl['policy']=frozenset()
    assert query(second,second.snapshot_id,(1,0),'manual-v1','u1',acl)==[]
    expect(lambda:query(replace(second,chunks=second.chunks+first.chunks),second.snapshot_id,
           (1,0),'manual-v1','u1',acl),'SNAPSHOT_MISMATCH')
    expect(lambda:build([s1,s1],'manual-v1'),'DUPLICATE_DOCUMENT')
    expect(lambda:build([replace(s1,blocks=(block,block))],'manual-v1'),'DUPLICATE_BLOCK')
    expect(lambda:query(second,first.snapshot_id,(1,0),'manual-v1','u1',acl),'SNAPSHOT_MISMATCH')
    print(json.dumps({'status':'SELF_CHECK_OK','delta':delta(first,second),
                     'unverified_ocr_excluded':True,'revoked_results':0},sort_keys=True))

if __name__ == '__main__':
    main()
